public static T NextPermutation<T>(T mask) where T : IBinaryInteger<T>
{
    T c = mask & -mask;
    T r = mask + c;
    return (((r ^ mask) >>> (int.CreateTruncating(T.TrailingZeroCount(c)) + 2))) | r;
}$END$

