public static T BinarySearch<T>(T lo, T hi, Func<T, bool> predicate) where T : IBinaryInteger<T>
{
    while (lo <= hi)
    {
        T mid = lo + ((hi - lo) >> 1);

        if (predicate(mid))
            hi = mid - T.One;
        else
            lo = mid + T.One;
    }

    return lo;
}$END$

