public static int UpperBound<T>(IReadOnlyList<T> source, int lo, int hi, T target, IComparer<T> comparer)
{
    while (lo <= hi)
    {
        int mid = lo + ((hi - lo) >> 1);

        if (comparer.Compare(source[mid], target) > 0)
            hi = mid - 1;
        else
            lo = mid + 1;
    }

    return lo;
}$END$

